```bash
cat <<'EOF' > test_proxy_handler.go
package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
)

func main() {
	// Test cases for Forwarded header parsing
	testCases := []struct {
		headerValue string
		expected    string
	}{
		{"for=192.0.2.43", "192.0.2.43"},
		{"for=192.0.2.43,", "192.0.2.43"}, // Trailing comma
		{"for=192.0.2.43, for=198.51.100.17", "192.0.2.43"}, // Multiple for parameters
		{"For=192.0.2.43", "192.0.2.43"}, // Case insensitive
		{"for=192.0.2.43;by=203.0.113.60;proto=http;host=example.com", "192.0.2.43"},
		{"by=203.0.113.60;for=192.0.2.43;proto=http;host=example.com", "192.0.2.43"},
		{"for=\"[2001:db8:cafe::17]:4711\"", "2001:db8:cafe::17"}, // IPv6 with port and quotes
		{"for=192.0.2.43:443", "192.0.2.43"}, // With port
		{"for=192.0.2.43, for=198.51.100.17;by=203.0.113.60", "192.0.2.43"}, // Complex case
	}

	fmt.Println("Testing parseForwardedHeader function:")
	for _, tc := range testCases {
		result := parseForwardedHeader(tc.headerValue)
		status := "FAIL"
		if result == tc.expected {
			status = "PASS"
		}
		fmt.Printf("[%s] Input: %q, Expected: %q, Got: %q\n", status, tc.headerValue, tc.expected, result)
	}
}

// Copied from proxy_handler.go for testing
func parseForwardedHeader(fwd string) string {
	splits := strings.Split(fwd, ";")
	if len(splits) == 0 {
		return ""
	}

	for _, split := range splits {
		trimmed := strings.TrimSpace(split)
		if strings.HasPrefix(strings.ToLower(trimmed), "for=") {
			forSplits := strings.Split(trimmed, ",")
			if len(forSplits) == 0 {
				return ""
			}

			addr := forSplits[0][4:]
			trimmedAddr := strings.
				NewReplacer("\"", "", "[", "", "]", "").
				Replace(addr) // If IpV6, remove brackets and quotes.

			return trimmedAddr
		}
	}

	return ""
}
EOF
```

